<?php
declare(strict_types=1);namespace Vendi\Sales;use PDO;use RuntimeException;
final class ReturnTraceabilityService{public function __construct(private PDO$db){}
 public function restore(int$b,int$branch,int$u,int$refundId,int$refundItemId,array$i,float$qty):void{$ratio=$qty/(float)$i['qty'];$this->db->prepare("UPDATE inventory SET qty=qty+? WHERE business_id=? AND branch_id=? AND product_id=?")->execute([$qty,$b,$branch,$i['product_id']]);if($i['variant_id'])$this->db->prepare("UPDATE variant_inventory SET quantity=quantity+? WHERE branch_id=? AND variant_id=?")->execute([$qty,$branch,$i['variant_id']]);
 $need=$qty;$lots=$this->db->prepare("SELECT * FROM sale_item_lots WHERE sale_item_id=? AND quantity_base>returned_quantity_base ORDER BY id FOR UPDATE");$lots->execute([$i['id']]);foreach($lots->fetchAll() as$l){if($need<=0)break;$available=(float)$l['quantity_base']-(float)$l['returned_quantity_base'];$take=min($need,$available);$this->db->prepare("UPDATE sale_item_lots SET returned_quantity_base=returned_quantity_base+? WHERE id=?")->execute([$take,$l['id']]);$this->db->prepare("UPDATE inventory_lots SET qty_base=qty_base+? WHERE id=?")->execute([$take,$l['lot_id']]);$this->db->prepare("INSERT INTO refund_item_lots(refund_item_id,lot_id,quantity_base) VALUES(?,?,?)")->execute([$refundItemId,$l['lot_id'],$take]);$need-=$take;}if($lots->rowCount()&&$need>0.000001)throw new RuntimeException('No coincide el saldo de lotes devuelto.');
 $serials=$this->db->prepare("SELECT sis.serial_id FROM sale_item_serials sis WHERE sis.sale_item_id=? AND sis.returned_at IS NULL ORDER BY sis.serial_id FOR UPDATE");$serials->execute([$i['id']]);$rows=$serials->fetchAll();if($rows){if(abs($qty-round($qty))>0.000001)throw new RuntimeException('Las series requieren devolución por unidad completa.');if(count($rows)<(int)$qty)throw new RuntimeException('No hay suficientes series pendientes de devolución.');foreach(array_slice($rows,0,(int)$qty) as$sr){$this->db->prepare("UPDATE inventory_serials SET status='available',sale_id=NULL,branch_id=? WHERE id=? AND status='sold'")->execute([$branch,$sr['serial_id']]);$this->db->prepare("UPDATE sale_item_serials SET returned_at=NOW() WHERE sale_item_id=? AND serial_id=?")->execute([$i['id'],$sr['serial_id']]);$this->db->prepare("INSERT INTO refund_item_serials(refund_item_id,serial_id) VALUES(?,?)")->execute([$refundItemId,$sr['serial_id']]);}}
 $components=$this->db->prepare("SELECT * FROM sale_item_components WHERE sale_item_id=? AND quantity_base>returned_quantity_base FOR UPDATE");$components->execute([$i['id']]);foreach($components->fetchAll() as$c){$target=(float)$c['quantity_base']*$ratio;$available=(float)$c['quantity_base']-(float)$c['returned_quantity_base'];$take=min($target,$available);if($take<=0)continue;$this->db->prepare("UPDATE sale_item_components SET returned_quantity_base=returned_quantity_base+? WHERE id=?")->execute([$take,$c['id']]);$this->db->prepare("UPDATE inventory SET qty=qty+? WHERE business_id=? AND branch_id=? AND product_id=?")->execute([$take,$b,$branch,$c['component_product_id']]);if($c['component_variant_id'])$this->db->prepare("UPDATE variant_inventory SET quantity=quantity+? WHERE branch_id=? AND variant_id=?")->execute([$take,$branch,$c['component_variant_id']]);$this->db->prepare("INSERT INTO refund_item_components(refund_item_id,component_product_id,component_variant_id,quantity_base) VALUES(?,?,?,?)")->execute([$refundItemId,$c['component_product_id'],$c['component_variant_id'],$take]);}
 $this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,user_id,variant_id,type,qty,reference_type,reference_id) VALUES(?,?,?,?,?,'return',?,'refund',?)")->execute([$b,$branch,$i['product_id'],$u,$i['variant_id'],$qty,$refundId]);}
}